     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_STYLE_CODE_RECIPE = 'ZimmProductStyleCode';
     5	
     6	// Hardcoded UI copy, not a prop and not a CMS lookup — see the note on the component below.
     7	// Named rather than inlined so the string sits at the top of the file, the same way
     8	// zimmSubscribeModal/index.tsx keeps PRIVACY_CONSENT_COPY and ACCESSIBILITY_DISCLAIMER_COPY.
     9	const LABEL = 'Style Code:';
    10	
    11	type ZimmProductStyleCodeProps = {
    12	  /**
    13	   * The master product's style number. This is the style code shown to shoppers, which is not
    14	   * the same value as the variant `product.id`.
    15	   */
    16	  value?: string;
    17	};
    18	
    19	/**
    20	 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
    21	 *
    22	 * The label is the hardcoded LABEL constant above rather than CMS microcopy: useContentful.ts
    23	 * requests entries with no `locale` parameter, so a `uiCopy` lookup would serve the space
    24	 * default to all eight storefronts regardless of site. zimmSubscribeModal/index.tsx hardcodes
    25	 * its copy the same way.
    26	 */
    27	export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
    28	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_STYLE_CODE_RECIPE, {});
    29	  if (!value) return null;
    30	
    31	  return (
    32	    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
    33	      <chakra.span __css={styles.label}>{LABEL}</chakra.span>
    34	      {/*
    35	        A real space so `textContent` — what a screen reader reads out and what a shopper
    36	        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
    37	        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
    38	        so the 4px `gap` in the recipe remains the only spacing.
    39	      */}{' '}
    40	      <chakra.span __css={styles.value}>{value}</chakra.span>
    41	    </chakra.div>
    42	  );
    43	};
