     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';
     5	
     6	type ZimmProductPriceProps = {
     7	  /**
     8	   * The price, already formatted for the storefront's locale and currency by the caller
     9	   * (`intl.formatNumber` at the page). This atom does no formatting of its own so it stays
    10	   * usable from Storybook without an intl provider.
    11	   *
    12	   * Optional because the page's mapper resolves an absent price to `''` rather than to a
    13	   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
    14	   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
    15	   * unchanged and the decision not to render is taken here.
    16	   */
    17	  price?: string;
    18	  /** Reserved for SFCC-194's was/now treatment; only `default` is implemented today. */
    19	  variant?: 'default';
    20	};
    21	
    22	/**
    23	 * Atom — the single, full product price. Styling lives in `zimmProductPrice.css.ts` and is
    24	 * consumed through the theme, per the one-canonical-styling-surface rule.
    25	 *
    26	 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
    27	 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
    28	 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
    29	 */
    30	export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPriceProps) => {
    31	  // Guard below the hook, never above it: an early return before `useStyleConfig` makes the
    32	  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather than a
    33	  // warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
    34	  const styles = useStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
    35	  if (!price) return null;
    36	
    37	  return (
    38	    /*
    39	     * `aria-live`/`aria-atomic` sit on the price element itself, so this atom still renders
    40	     * exactly one node.
    41	     *
    42	     * WCAG 2.2 AA 4.1.3 (Status Messages) is the requirement. Choosing a variant rewrites the
    43	     * URL's `pid` (`pages/product-detail/index.tsx` lines 328-338), which re-keys the
    44	     * `useProduct` call on line 205 and hands this atom a different string. Focus never moves,
    45	     * so without a live region the price is repainted silently and a screen-reader user is never
    46	     * told the number they are buying at has changed. React mutates this element's text in
    47	     * place, which is exactly the change a live region reports; `aria-atomic` makes it read the
    48	     * whole price rather than only the characters that differ.
    49	     *
    50	     * Base `display-price/current-price.jsx` instead puts the announcement in a second, hidden
    51	     * node (its lines 57-66). It needs one because it prefixes a `labelForA11y` product name to
    52	     * order the name ahead of the price (its comment on line 56); this atom has no such prefix
    53	     * to order — `price` arrives already formatted and localised by the page and there is no
    54	     * `useIntl` here — so the extra node would carry a verbatim duplicate of the visible text.
    55	     * That costs twice: every screen reader would read the price twice on first load, and the
    56	     * extra child breaks `ZimmProductContent`'s `play` tests, which assert the exact child count
    57	     * of its flex column (`WithoutDescription`, `RhythmWithDescription`, `BlankDescription`).
    58	     */
    59	    <chakra.p __css={styles} textStyle="price" data-testid="product-price" aria-live="polite" aria-atomic="true">
    60	      {price}
    61	    </chakra.p>
    62	  );
    63	};
