=============== zimmProductPrice/index.test.tsx ===============
     1	/**
     2	 * Scoped to this atom's own contract per testing.md: given a formatted string or nothing, does
     3	 * it render the right branch, and does the price it renders stay announceable.
     4	 *
     5	 * Formatting is deliberately not asserted here — it happens at the page
     6	 * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
     7	 * renders whatever string it is handed. What is not proven anywhere else is the absent branch:
     8	 * the mapper resolves a missing price to `''`, so the empty case is a real production path and
     9	 * not a defensive edge case.
    10	 */
    11	import React from 'react';
    12	import { describe, test, expect } from 'vitest';
    13	import { render, screen } from '@testing-library/react';
    14	import { ZimmProductPrice } from './index';
    15	
    16	describe('ZimmProductPrice', () => {
    17	  test('renders the caller-formatted string verbatim', () => {
    18	    render(<ZimmProductPrice price="HK$6,200.00" />);
    19	    // Verbatim, not re-formatted: the currency symbol, grouping and decimals are all the
    20	    // page's decisions, and re-deriving any of them here would diverge per storefront.
    21	    expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
    22	  });
    23	
    24	  test('announces the price through a polite atomic live region', () => {
    25	    const { container } = render(<ZimmProductPrice price="HK$6,200.00" />);
    26	
    27	    // A variant change swaps this string with no focus move, so WCAG 2.2 AA 4.1.3 needs the
    28	    // update announced. Both attributes are asserted: dropping `aria-atomic` would let a screen
    29	    // reader announce only the characters that differ instead of the whole price, and neither
    30	    // loss shows up on screen, so nothing else would catch it.
    31	    const price = screen.getByTestId('product-price');
    32	    expect(price).toHaveAttribute('aria-live', 'polite');
    33	    expect(price).toHaveAttribute('aria-atomic', 'true');
    34	
    35	    // The live region is the price element itself, not an extra hidden twin. Asserted because
    36	    // the single-node shape is load-bearing, not incidental: `ZimmProductContent` renders this
    37	    // atom into a flex column whose own `play` tests assert that column's exact child count, so
    38	    // a second node here fails them from another folder.
    39	    expect(container.querySelectorAll('[aria-live]')).toHaveLength(1);
    40	    expect(container.firstChild).toBe(price);
    41	  });
    42	
    43	  test.each([undefined, ''])('renders nothing for %s', (price) => {
    44	    const { container } = render(<ZimmProductPrice price={price} />);
    45	    // `''` is what the page's mapper produces for a product with no price, so this branch is
    46	    // reached in production. An empty styled node would still consume a gap in
    47	    // ZimmProductContent's flex column, leaving a visible hole between name and description.
    48	    //
    49	    // Asserted as an empty container rather than an absent testid: a node that still carried the
    50	    // recipe's styling but had lost its `data-testid` would satisfy the narrower check while
    51	    // being precisely the gap-consuming element this guard exists to prevent.
    52	    expect(container).toBeEmptyDOMElement();
    53	  });
    54	});

