101:  test('component overrides are registered', () => {
102-    // ListMenu in particular: the base component reads
103-    // theme.components.ListMenu.baseStyle directly, so a missing entry throws
104-    // at render rather than falling back.
105-    expect(theme.components.Button).toBeTruthy();
106-    expect(theme.components.Header).toBeTruthy();
107-    expect(theme.components.ListMenu).toBeTruthy();
108-
109-    // The opposite failure mode, and the reason this list stays hand-maintained rather than
110-    // derived from the `components` map — a derived list moves with any unregistration and so
111-    // could never catch one. Where ListMenu throws, these three fail silently: `useStyleConfig`
112-    // and `useMultiStyleConfig` return an empty object for an unregistered recipe,
113-    // `__css={undefined}` is a legal prop, and the element quietly inherits instead. For the two
114-    // atoms the whole recipe is `margin: 0` and one colour, so an unregistration is very nearly
115-    // invisible: the base template's own `styles.js` sets `color: 'gray.900'` on the body, and the
116-    // gray scale in play is SFCC's, not Chakra's — its `foundations/colors.js` replaces the whole
117-    // scale before our overrides merge. SFCC's `gray.900` is #181818 against the brand's #191919,
118-    // one unit per channel, which no visual review will catch. ZimmProductMeta's resolved 28px is
119-    // additionally pinned in its own suite; the two atoms have only this.
120-    expect(theme.components.ZimmProductMeta).toBeTruthy();
121-    expect(theme.components.ZimmProductName).toBeTruthy();
122-    expect(theme.components.ZimmProductModelInfo).toBeTruthy();
123-  });
124-});
125-
126-describe('scale token collisions — Chakra keeps its own meanings', () => {
127-  test('fontSizes are NOT remapped to the Zimmermann scale', () => {
128-    // Design system: md 24px, xs 16px, 2xs 14px, 3xs 12px, 4xs 10px.
129-    // Chakra: md 16px, xs 12px, 2xs 10px, 3xs 7.2px — four collisions.
130-    // Type is set via `textStyle`, never a raw `fontSize` token, precisely so
131-    // these two scales never have to agree. If this test fails, someone has
132-    // remapped the scale and every base-component `fontSize` shifted with it.
133-    expect(theme.fontSizes.md).toBe('1rem');
134-    expect(theme.fontSizes.xs).toBe('0.75rem');
135-    expect(theme.fontSizes['2xs']).toBe('0.625rem');
136-  });
137-
138-  test('transition durations are NOT remapped to the Zimmermann motion scale', () => {
139-    // Zimmermann motion: fast 200ms, default 300ms, slow 500ms.
140-    // Chakra: fast 150ms, slow 300ms. Component overrides import the `motion`
141-    // constants directly instead, the same way they import FONT_MEDIUM.

=== productInfo.ts :45-65 ===
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the static-information components, or `null` while the product loads.
 */
export const selectPdpProductInfo = (
  product: PdpSourceProduct | undefined | null,
  priceData: PdpSourcePrice | undefined | null,
  currency: string,
  formatPrice: FormatPrice,
): PdpProductInfo | null => {
  if (!product?.name) return null;

  return {
    name: product.name,
    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
    description: product.longDescription,
    modelInfo: product.c_modelFit,
    // The style code shoppers see is the *master* style number. `product.id` is the variant
    // SKU once a size is selected, so reading it would silently show a different value after
    // the first swatch click. Standard products have no master, and there `id` is correct.
    styleCode: product.master?.masterId ?? product.id,
  };

