import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
import { ZimmProductModelInfo } from 'app/components/ui-kits/atoms/zimmProductModelInfo';
import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode';

const PROPS = [
  'fontSize', 'lineHeight', 'fontWeight', 'fontFamily', 'letterSpacing',
  'textTransform', 'color', 'margin', 'display', 'gap', 'paddingInlineStart',
] as const;

const dump = (label: string, node: React.ReactElement, testid: string) => {
  const { getByTestId } = render(<ChakraProvider theme={theme}>{node}</ChakraProvider>);
  const el = getByTestId(testid);
  const s = window.getComputedStyle(el);
  const out = PROPS.map((p) => `${p}=${s[p as never] || '-'}`).join(' | ');
  console.log(`PROBE ${label} :: ${out}`);
};

