/**
 * Scoped to this atom's own contract per testing.md: given a value or no value, does it render
 * the right branch, does the label reach the DOM joined to the value as one readable line, and
 * is that label *sourced* from `react-intl` rather than written into the component.
 *
 * The recipe's own resolution is covered by theme/components/recipeGuards.test.ts and
 * ui-kits/recipeParts.test.ts; the visual result is covered by index.stories.tsx. Neither of
 * those proves the absent-value branch is discoverable from this folder, which is what this is.
 *
 * Every render is wrapped: the atom calls `useIntl()`, which throws outside an `IntlProvider`
 * (react-intl's `invariantIntlContext`). `.storybook/preview.tsx` supplies one for the stories;
 * Vitest has no global provider, so it is supplied here.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmProductStyleCode } from './index';

/** The id the component asks for. Repeated deliberately — see the sourcing test below. */
const LABEL_ID = 'product_view.label.style_code';

/**
 * `locale` matches `defaultLocale` so react-intl treats an absent message as the ordinary
 * fallback-to-`defaultMessage` path rather than a missing-translation error.
 */
const renderWithIntl = (ui: React.ReactElement, messages?: Record<string, string>) =>
  render(
    <IntlProvider locale="en-AU" defaultLocale="en-AU" messages={messages}>
      {ui}
    </IntlProvider>,
  );

describe('ZimmProductStyleCode', () => {
  test('renders the label and value as one readable line', () => {
    renderWithIntl(<ZimmProductStyleCode value="8637DS241" />);
    // The DS models label and value as two nodes; a screen reader and a copy-paste must still
    // see the single string both composed page designs show. With no message supplied this is
    // the `defaultMessage` path, which is what every locale renders until extraction runs.
    expect(screen.getByTestId('product-style-code').textContent).toBe('Style Code: 8637DS241');
  });

  test('takes the label from the intl provider rather than a literal in the component', () => {
    // The guard against a regression to `const LABEL = 'Style Code:'`. A hardcoded English
    // literal ships one language to all eleven locales, and it is invisible: the test above
    // passes either way, because `defaultMessage` and the old literal are the same string.
    // Supplying a different message for the same id is the only thing that tells them apart —
    // an inlined literal cannot change, so this assertion can only pass if the label was looked
    // up. The value must stay untouched, since it is a prop and not translatable copy.
    renderWithIntl(<ZimmProductStyleCode value="8637DS241" />, { [LABEL_ID]: 'Code de style :' });

    expect(screen.getByTestId('product-style-code').textContent).toBe('Code de style : 8637DS241');
  });

  test.each([undefined, ''])('renders nothing for %s', (value) => {
    renderWithIntl(<ZimmProductStyleCode value={value} />);
    // The page places this unconditionally, so an absent style code must collapse rather than
    // leave an empty styled node contributing to the stack's rhythm.
    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
  });
});
